/// Returns true if `candidate` is a prime number (greater than 1
/// and divisible only by 1 and itself), false otherwise.
pub fn test_prime(candidate: u64) -> bool {
    // Handle small cases and even numbers.
    if candidate <= 1 {
        return false;
    }
    if candidate == 2 {
        return true;
    }
    if candidate % 2 == 0 {
        return false;
    }

    // Check odd divisors up to sqrt(candidate).
    // We avoid overflow by comparing i <= candidate / i.
    let mut i = 3;
    while i <= candidate / i {
        if candidate % i == 0 {
            return false;
        }
        i += 2;
    }

    true
}

